const { test } = require("node:test");
const assert = require("node:assert/strict");
const { startServer, api } = require("./helpers");

test("pagination composes with warehouseId and low filters", async () => {
  const { base, close } = startServer();
  try {
    const w1 = (await api(base, "POST", "/api/warehouses", { name: "W1", location: "x" })).json.id;
    const w2 = (await api(base, "POST", "/api/warehouses", { name: "W2", location: "x" })).json.id;

    // 5 items in w1 (3 low-stock), 5 items in w2 (0 low-stock)
    for (let i = 0; i < 5; i++) {
      await api(base, "POST", "/api/items", {
        sku: `W1-${i}`, name: `W1 item ${i}`, warehouseId: w1,
        quantity: i < 3 ? 0 : 10, reorderThreshold: 2,
      });
    }
    for (let i = 0; i < 5; i++) {
      await api(base, "POST", "/api/items", {
        sku: `W2-${i}`, name: `W2 item ${i}`, warehouseId: w2,
        quantity: 10, reorderThreshold: 2,
      });
    }

    // Filtered to w1's 3 low-stock items, page 1 of size 2.
    const page1 = await api(base, "GET", `/api/items?warehouseId=${w1}&low=true&page=1&pageSize=2`);
    assert.equal(page1.status, 200);
    assert.equal(page1.json.total, 3, "total must reflect the FILTERED count, not the unfiltered one");
    assert.equal(page1.json.items.length, 2);
    for (const it of page1.json.items) {
      assert.equal(it.warehouseId, w1);
      assert.ok(it.quantity <= it.reorderThreshold);
    }

    const page2 = await api(base, "GET", `/api/items?warehouseId=${w1}&low=true&page=2&pageSize=2`);
    assert.equal(page2.json.items.length, 1, "page 2 must have the 3rd filtered item, not an empty/wrong slice");
    assert.equal(page2.json.total, 3);

    const badPage = await api(base, "GET", "/api/items?page=0");
    assert.equal(badPage.status, 400);
    const badSize = await api(base, "GET", "/api/items?pageSize=101");
    assert.equal(badSize.status, 400);
  } finally {
    await close();
  }
});

